INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-248-1', 'doc-card-248', 'definition', 'تعریف', 'ارتباطات میان‌فردی / ارتباطات غیرکلامی

افراد درباره‌ی رفتار ارتباطی دیگران انتظاراتی دارند که از هنجارهای اجتماعی و شناخت قبلی شکل می‌گیرد. نقض این انتظارات توجه و برانگیختگی ایجاد می‌کند و فرد آن را تفسیر و ارزیابی می‌کند. پیامد نقض به ارزش نقض و «ارزش پاداش» ارتباط‌گر بستگی دارد؛ نقض مثبت از سوی فردی با ارزش پاداش بالا ممکن است از رفتار مطابق انتظار اثربخش‌تر باشد.', '1b9599158a526d650e3b496de4914e90d7a2ec0b732a451cb18e74d3e1fee43d', 1, NOW(), NOW()),
